SELECT DATE_TRUNC('MONTH', txn_time) AS txn_month, SUM(CASE WHEN txn_type = 'DEBIT' THEN 1 ELSE 0 END) AS debit_count, SUM(CASE WHEN txn_type = 'DEBIT' THEN amount ELSE 0 END) AS debit_amount, ROUND(STDDEV(amount), 2) AS stddev_amount FROM transactions WHERE amount IS NULL GROUP BY DATE_TRUNC('MONTH', txn_time) HAVING ROUND(STDDEV(amount), 2) > 66 ORDER BY debit_amount, txn_month LIMIT 1
